function icon(name,size=20,cls=''){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" class="${cls}" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;}
function brand(extra=''){return `<a class="brand ${extra}" href="#/dashboard" aria-label="بیلتو؛ صفحه اصلی"><svg class="brand-icon" viewBox="0 0 38 44" fill="none" aria-hidden="true"><path d="M3 21 19 6l16 15v20H24V29H14v12H3Z" fill="currentColor"/><path d="M26 4h7v13l-7-6Z" fill="#6bb4ff"/><path d="m12 20 7-7 8 7-7 7Z" fill="#a3d3ff"/></svg><span>بیلتو<small>همراه ساخت‌وساز شما</small></span></a>`;}
