  return `<svg class="building-art" viewBox="0 0 460 290" fill="none" aria-hidden="true" preserveAspectRatio="xMidYMid ${hero?'meet':'slice'}"><defs><linearGradient id="${id}sky" x2=".5" y2="1"><stop stop-color="${hero?'#0b559e':variant?'#dfeae7':'#d8e7f1'}"/><stop offset="1" stop-color="${hero?'#4b91c8':variant?'#f3f5ed':'#f0f4f5'}"/></linearGradient><linearGradient id="${id}glass" x2="1" y2="1"><stop stop-color="#47768e"/><stop offset="1" stop-color="#163b55"/></linearGradient><linearGradient id="${id}wall" x2="1" y2=".5"><stop stop-color="#fff"/><stop offset="1" stop-color="#c5d6e0"/></linearGradient></defs><path fill="url(#${id}sky)" d="M0 0h460v290H0z" opacity="${hero?'.02':'1'}"/>${!hero?'<circle cx="360" cy="55" r="25" fill="#fff" opacity=".6"/><path d="M0 200 70 168l83 25 130-27 177 33v91H0" fill="#b9cdd1" opacity=".3"/>':''}<ellipse cx="242" cy="261" rx="181" ry="20" fill="${hero?'#02214c':'#6e8c9d'}" opacity=".17"/><path d="m83 230 144-65 169 67-149 51Z" fill="${hero?'#5e9bca':'#c8d5d8'}"/><path d="m119 116 122-59 120 58-120 60Z" fill="#f6fbff"/><path d="m241 175 120-60v122l-120 48Z" fill="#a8c2d2"/><path d="m119 116 122 59v110l-122-56Z" fill="url(#${id}wall)"/><path d="m131 124 97 47v31l-97-46Z" fill="url(#${id}glass)"/><path d="m131 169 97 47v48l-97-44Z" fill="url(#${id}glass)"/><path d="m254 175 93-46v34l-93 44ZM254 220l93-43v48l-93 36Z" fill="url(#${id}glass)"/><path d="M163 140v29m32-14v29m-32 1v48m32-33v48m89-87v35m32-50v35m-32 12v47m32-61v48" stroke="#b6d0df" stroke-width="4"/><path d="m110 158 131 62 129-62v10l-129 63-131-63ZM110 112l131 63 129-63v11l-129 63-131-63Z" fill="#f6fbff"/><path d="m119 116 122-59 120 58-120 60Zm122 59v110" stroke="#d5e1e7" stroke-width="2"/><path d="m161 93 80-38 77 38-80 39Z" fill="#b5c9d5"/><path d="m165 91 76-36 74 36-77 37Z" fill="#e6eff5"/><path d="m174 91 67-30 61 30-65 31Z" fill="#d4e1e9"/><path d="m119 229 122 56 120-48v-9l-120 48-122-56Z" fill="#eaf2f7"/><path d="m191 248 20 10v-38l-20-9Z" fill="#e3c9a4"/><path d="m215 262 26 13v-53l-26-12Z" fill="#b5c7d3"/><path d="m260 253 40-17v-12l-40 18Z" fill="#f6fcff"/>${hero?'<path d="M68 91V248m-13-157h120M66 91l54-40 55 40m-55-40v40m53 0v35m-6 0h13" stroke="#92c7ed" stroke-width="2" opacity=".55"/><path d="m60 246 8-155 9 155" stroke="#92c7ed" stroke-width="2" opacity=".45"/>':''}<g fill="${hero?'#2d927f':'#73967b'}"><ellipse cx="95" cy="218" rx="16" ry="25"/><ellipse cx="379" cy="218" rx="16" ry="29"/><ellipse cx="72" cy="240" rx="20" ry="10"/><ellipse cx="372" cy="252" rx="27" ry="11"/></g><path d="M95 220v31m284-35v36" stroke="${hero?'#86c4b2':'#6e806a'}" stroke-width="3"/><path d="m138 261 43-17 21 10-43 17Z" fill="#eef5f8" opacity=".5"/></svg>`;
