function materialArt(type){
 const shapes={steel:'<g transform="translate(7 8)" stroke="#7b93aa" stroke-width="1"><path d="m0 16 27-13 6 10L6 27Z" fill="#647e91"/><path d="m0 10 27-13 6 10L6 21Z" fill="#344f63"/><path d="m1 4 27-13 6 10L7 15Z" fill="#92a6b3"/><path d="m5 5 27-13M5 11l27-13M5 17l27-13"/></g>',cement:'<path d="m12 7 20-2 6 33-26 4-4-29Z" fill="#c5bba4"/><path d="m12 11 21-3 3 17-25 3Z" fill="#178be5"/><path d="m15 16 15-2m-14 6 15-2" stroke="white" stroke-width="2"/><path d="m14 33 18-3" stroke="#8e8778"/>',brick:'<path d="m5 15 23-9 16 8-24 10Z" fill="#e2a17d"/><path d="m5 15 15 9v18L5 33Z" fill="#ba6442"/><path d="m20 24 24-10v19L20 42Z" fill="#d5835d"/><path d="m9 15 5-2 4 2-5 2Zm9-4 5-2 4 2-5 2Zm5 7 5-2 4 2-5 2Zm9-4 5-2 3 2-5 2Z" fill="#8b4933"/><path d="M10 22v11m5-9v11" stroke="#e9ad88"/>',pipe:'<g fill="#273f56" stroke="#7f9bad" stroke-width="1.5"><ellipse cx="24" cy="14" rx="17" ry="9"/><ellipse cx="24" cy="22" rx="17" ry="9"/><ellipse cx="24" cy="30" rx="17" ry="9"/></g><g fill="#8aa4b4"><ellipse cx="24" cy="14" rx="10" ry="3"/><ellipse cx="24" cy="22" rx="10" ry="3"/><ellipse cx="24" cy="30" rx="10" ry="3"/></g>',sand:'<path d="m3 33 11-15 9-6 10 10 12 14-19 8Z" fill="#d4bb91"/><path d="m14 18 9-6 1 21-21 0Zm10 15 9-11 12 14-19 8Z" fill="#e4cca4"/><path d="m13 31 6-5m8 12 7-6" stroke="#b89c72"/>',block:'<path d="m5 17 24-9 15 9-24 10Z" fill="#e3e7ea"/><path d="m5 17 15 10v15L5 33Z" fill="#c0ccd3"/><path d="m20 27 24-10v15L20 42Z" fill="#d4dce0"/><path d="m9 17 8-3 6 3-8 3Zm14-5 6-2 8 7-8 2Z" fill="#8b9aa4"/>'};
 return `<svg viewBox="0 0 48 48" fill="none" aria-hidden="true">${shapes[type]||shapes.block}</svg>`;
}
function art(type){return type==='building'?buildingArt():`<svg viewBox="0 0 460 210" aria-hidden="true"><rect width="460" height="210" fill="${type==='steel'?'#e9eff4':'#eaf2f8'}"/><circle cx="340" cy="40" r="110" fill="#fff" opacity=".4"/><g transform="translate(140 20) scale(3.7)">${type==='plan'?'<rect x="5" y="2" width="34" height="44" rx="3" fill="white"/><path d="M11 13h22v25H11zM11 24h22M22 13v25M11 18h5M28 30h5" fill="none" stroke="#90b2d5" stroke-width="1.3"/><path d="m31 7 4-4 3 3-4 4-3 12-3-3Z" fill="#267cdb"/>':materialArt('steel').replace(/<svg[^>]*>|<\/svg>/g,'')}</g></svg>`;}

const initialState={profile:{name:'محمد',phone:'',email:'',city:'تهران'},projects:[{id:'demo-villa',name:'خانه ویلایی نیاوران',city:'تهران',type:'residential',area:200,floors:2,structure:'concrete',quality:'standard',budget:7400000000,progress:70,stage:4,createdAt:'2026-10-01T10:00:00Z'},{id:'demo-commercial',name:'ساختمان تجاری آفتاب',city:'کرج',type:'commercial',area:350,floors:3,structure:'steel',quality:'standard',budget:20450640000,progress:25,stage:1,createdAt:'2026-10-05T10:00:00Z'}],favorites:[],requests:[],settings:{tips:true},onboarded:false};
let state;
try{const saved=JSON.parse(localStorage.getItem('bilto.v1'));state=saved&&Array.isArray(saved.projects)&&saved.profile?{...structuredClone(initialState),...saved,settings:{...initialState.settings,...saved.settings}}:structuredClone(initialState);}catch{state=structuredClone(initialState);}
let storageOK=true;
function save(){try{localStorage.setItem('bilto.v1',JSON.stringify(state));return true;}catch{storageOK=false;toast('ذخیره‌سازی مرورگر در دسترس نیست؛ از تنظیمات خروجی بگیرید.');return false;}}
let currentFilter='همه', searchTerm='', detailTab='overview', settingTab='profile', savedOnly=false, toastTimer, lastFocus, activeDialog, pendingOnboarding=false;
const route=()=>location.hash.slice(1)||'/dashboard';
const navItems=[['/dashboard','home','خانه'],['/projects','project','پروژه‌های من'],['/estimate','calculator','برآورد هزینه'],['/materials','material','قیمت مصالح'],['/contractors','people','پیمانکاران'],['/guide','book','راهنمای ساخت']];
function navLink(path,name,label){const active=route()===path||(path==='/projects'&&(route().startsWith('/project/')||route()==='/new-project'))||(path==='/materials'&&route().startsWith('/compare'))||(path==='/contractors'&&route().startsWith('/contractor/'))||(path==='/guide'&&route().startsWith('/article/'));return `<a href="#${path}" class="nav-link ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(name)}${label}</a>`;}
function shell(page){
 const active=navItems.find(([p])=>route()===p)?.[2]||({'/settings':'حساب کاربری','/faq':'سؤالات متداول','/new-project':'پروژه جدید','/requests':'درخواست‌های من'}[route()])||'جزئیات';
 const date=new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'long',year:'numeric'}).format(new Date());
 return `<div class="app-shell"><aside class="sidebar" id="sidebar">${brand()}<div class="nav-label">میز کار شما</div><nav aria-label="منوی اصلی">${navItems.map(n=>navLink(...n)).join('')}</nav><div class="nav-separator"></div><nav aria-label="راهنما و تنظیمات">${navLink('/faq','help','سؤالات متداول')}${navLink('/settings','settings','تنظیمات')}</nav><div class="sidebar-bottom"><div class="sidebar-promo">${icon('home',83,'promo-icon')}<h3>شروع یک ساخت‌وساز بهتر</h3><p>قدم اول را با اطمینان بردارید.</p><a href="#/new-project">ایجاد پروژه جدید ${icon('arrow',13)}</a></div><a class="sidebar-user" href="#/settings"><span class="avatar">${esc(state.profile.name.slice(0,1))}</span><div><strong>${esc(state.profile.name)}</strong><p class="muted small">حساب شخصی</p></div>${icon('chevron',15,'chevron')}</a></div></aside><button class="menu-scrim" aria-label="بستن منو" data-action="menu-close"></button><div class="main-wrap"><header class="topbar">${brand('mobile-brand')}<div class="breadcrumb">میز کار ${icon('chevron',12)} <strong>${active}</strong></div><form class="top-search" id="global-search">${icon('search',15)}<input aria-label="جست‌وجو در راهنمای ساخت" placeholder="دنبال چه چیزی می‌گردید؟" name="q" autocomplete="off"></form><span class="date">${date}</span><button class="icon-btn" data-action="notifications" aria-label="اعلان‌ها">${icon('bell',19)}<span class="notification-dot"></span></button><a class="avatar" href="#/settings" aria-label="حساب کاربری">${esc(state.profile.name.slice(0,1))}</a><button class="icon-btn mobile-menu" data-action="menu-open" aria-label="باز کردن منو">${icon('menu',22)}</button></header><main class="content" id="main-content">${page}<footer class="footer"><span>${brand().replace(/<small>.*?<\/small>/,'').replace('class="brand "','class="brand " style="font-size:14px;gap:5px"').replace('class="brand-icon"','class="brand-icon" style="width:17px;height:19px"')} <span style="margin-right:10px">برای ساختن فردایی بهتر</span></span><span><i class="footer-dot"></i> نسخه نمایشی · داده‌ها در این مرورگر ذخیره می‌شوند</span></footer></main></div><nav class="bottom-nav" aria-label="ناوبری موبایل">${[['/dashboard','home','خانه'],['/projects','project','پروژه‌ها'],['/new-project','plus','جدید'],['/materials','material','مصالح'],['/settings','user','حساب من']].map(([p,i,l])=>`<a href="#${p}" class="${route()===p?'active':''} ${i==='plus'?'add-project':''}" aria-label="${l}" ${route()===p?'aria-current="page"':''}>${icon(i,21)}${i==='plus'?'':`<span>${l}</span>`}</a>`).join('')}</nav></div>`;
}
function head(title,subtitle='',action=''){return `<div class="page-head"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;}
const newButton=()=>`<a class="btn" href="#/new-project">${icon('plus',17)} پروژه جدید</a>`;
const sectionTitle=(title,link='',label='مشاهده همه',count='')=>`<div class="section-title"><h2>${title}${count!==''?`<span class="count">${fa(count)}</span>`:''}</h2>${link?`<a class="text-btn" href="#${link}">${label} ${icon('arrow',14)}</a>`:''}</div>`;
function projectCard(p,i=0){return `<article class="project-card"><a href="#/project/${encodeURIComponent(p.id)}"><div class="project-image ${i%2?'alt':''}">${buildingArt(i%2)}<span class="badge">${projectTypes[p.type]||'پروژه'}</span></div><div class="project-body"><h3>${esc(p.name)}</h3><div class="project-meta">${icon('pin',12)}${esc(p.city)}<span class="dot">·</span>${fa(p.area*p.floors)} مترمربع</div><div class="progress-label"><span>${stages[p.stage]||stages[0]}</span><strong>${fa(p.progress)}٪</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Number(p.progress)}%"></div></div><div class="project-foot"><span>برآورد کل هزینه</span><b>${billions(p.budget)} <span class="muted" style="font-size:8px;font-weight:400">میلیارد تومان</span></b></div></div></a></article>`;}
function changeLabel(m){return `<span class="change ${m.change>0?'up':m.change<0?'down':'flat'}">${m.change===0?'بدون تغییر':`${m.change>0?'↗':'↘'} ${fa(Math.abs(m.change))}٪`}</span>`;}
function empty(title='نتیجه‌ای پیدا نشد',desc='عبارت جست‌وجو یا فیلتر را تغییر دهید.',button=''){return `<div class="empty-state">${icon('search',38)}<h3>${title}</h3><p>${desc}</p>${button}</div>`;}
function articleCard(a){return `<article class="article-card"><a href="#/article/${a.id}"><div class="article-image">${art(a.visual)}</div><div class="article-body"><div class="eyebrow">${a.category}</div><h3>${a.title}</h3><p>${a.desc}</p><div class="article-footer"><span>${a.time.toLocaleString('fa-IR')} دقیقه مطالعه</span><span class="blue">مطالعه مقاله ${icon('arrow',12).replace('<svg ','<svg style="display:inline;vertical-align:middle" ')}</span></div></div></a></article>`;}
function dashboard(){
 const budget=state.projects.reduce((sum,p)=>sum+p.budget,0);
 return `${head(`<span class="greeting-line">سلام، ${esc(state.profile.name)} <span class="wave">☀️</span></span>`,'به خانهٔ ساخت‌وساز خودت خوش آمدی.',newButton())}<section class="hero"><div class="hero-grid"></div><span class="hero-caption">BUILD YOUR TOMORROW</span><div class="hero-copy"><div class="hero-tag"><i></i> از اولین قدم، تا آخرین آجر</div><h2>از زمین تا خانه،<br><span>با خیال راحت بساز!</span></h2><p>مدیریت پروژه، برآورد هزینه و انتخاب همراهان ساخت؛<br>همه در یک جا، ساده و شفاف.</p><a class="btn" href="#/new-project">شروع پروژه جدید ${icon('arrow',15)}</a></div><div class="hero-art">${buildingArt(0,true)}</div></section><div class="stats-grid">${[['project','پروژه‌های من',fa(state.projects.length),'پروژه',''],['calculator','بودجه برآوردشده',billions(budget),'میلیارد تومان','green'],['people','پیمانکاران نمونه',fa(contractors.length),'مجموعه','purple'],['bookmark','مصالح ذخیره‌شده',fa(state.favorites.length),'مورد','orange']].map(([i,l,v,u,c])=>`<div class="stat-card"><span class="stat-icon ${c}">${icon(i,21)}</span><div><p>${l}</p><strong>${v}<small>${u}</small></strong></div></div>`).join('')}</div><div class="dashboard-grid"><div><section>${sectionTitle('پروژه‌های من','/projects','همه پروژه‌ها',state.projects.length)}<div class="projects-grid">${state.projects.length?state.projects.slice(0,2).map(projectCard).join(''):empty('اولین پروژه‌ات را بساز','مسیر ساخت خانه‌ات از همین‌جا شروع می‌شود.',newButton())}</div></section><section class="dashboard-articles">${sectionTitle('یک قدم آگاهانه‌تر','/guide','راهنمای ساخت')}<div class="article-grid">${articles.slice(0,3).map(articleCard).join('')}</div></section></div><aside class="dashboard-side"><section class="quick-section">${sectionTitle('دسترسی سریع')}<div class="quick-grid">${[['/estimate','calculator','برآورد هزینه'],['/materials','material','قیمت مصالح'],['/contractors','people','پیمانکاران'],['/guide','book','راهنمای ساخت']].map(([p,i,l])=>`<a class="quick-item" href="#${p}"><span>${icon(i,21)}</span>${l}</a>`).join('')}</div></section><section class="panel market-panel">${sectionTitle('نبض بازار مصالح','/materials','همه قیمت‌ها')}${materials.slice(0,3).map(m=>`<a class="market-item" href="#/compare/${m.id}"><span class="material-art">${materialArt(m.visual)}</span><div><h3>${m.name}</h3><p>هر ${m.unit}</p></div><div class="market-price">${money(m.price)} ${changeLabel(m)}</div></a>`).join('')}<p class="sample-note">${icon('info',12)}قیمت‌ها نمونه و نمایشی هستند؛ تومان</p></section>${state.settings.tips?`<div class="tip-card">${icon('leaf',23)}<div><h3>خوب ساختن، از خوب دانستن شروع می‌شود.</h3><p>قبل از شروع، مسیر ساخت خانه‌ات را بشناس.</p><a class="text-btn" href="#/guide">مشاهده راهنمای قدم‌به‌قدم ${icon('arrow',13)}</a></div></div>`:''}</aside></div>`;
}
function projectsPage(){const list=state.projects.filter(p=>(currentFilter==='همه'||projectTypes[p.type]===currentFilter)&&`${p.name} ${p.city}`.includes(searchTerm));return `${head('پروژه‌های من','همه مسیرهای ساخت شما، در یک نگاه.',newButton())}<div class="toolbar">${searchField('جست‌وجوی پروژه یا شهر…')} ${chips(['همه',...Object.values(projectTypes)])}</div><div class="grid-3">${list.length?list.map(projectCard).join(''):empty(state.projects.length?'پروژه‌ای پیدا نشد':'هنوز پروژه‌ای نساخته‌اید',state.projects.length?'فیلتر یا عبارت جست‌وجو را تغییر دهید.':'اولین قدم را برای ساختن بردارید.',newButton())}</div>`;}
function searchField(placeholder){return `<div class="search-field">${icon('search',18)}<input id="page-search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(searchTerm)}" autocomplete="off"></div>`;}
function chips(values){return `<div class="chips">${values.map(c=>`<button class="chip ${currentFilter===c?'active':''}" data-action="filter" data-value="${c}" aria-pressed="${currentFilter===c}">${c}</button>`).join('')}</div>`;}
const cityOptions=(selected='تهران')=>['تهران','کرج','اصفهان','شیراز','مشهد','رشت'].map(c=>`<option ${selected===c?'selected':''}>${c}</option>`).join('');
function estimateFields(p={}){return `<div class="form-field"><label for="area">متراژ هر طبقه (مترمربع)</label><input id="area" name="area" inputmode="decimal" value="${esc(p.area||200)}" required><span class="field-help">مساحت ناخالص هر طبقه، بین ۲۰ تا ۱۰۰٬۰۰۰</span></div><div class="form-field"><label for="floors">تعداد طبقات</label><input id="floors" name="floors" inputmode="numeric" value="${esc(p.floors||2)}" required><span class="field-help">بین ۱ تا ۵۰ طبقه</span></div><div class="form-field"><label for="city">شهر پروژه</label><select id="city" name="city">${cityOptions(p.city)}</select></div><div class="form-field"><label for="structure">نوع سازه</label><select id="structure" name="structure"><option value="concrete" ${p.structure!=='steel'?'selected':''}>اسکلت بتنی</option><option value="steel" ${p.structure==='steel'?'selected':''}>اسکلت فلزی</option></select></div><div class="form-field full"><label for="quality">سطح کیفیت ساخت</label><select id="quality" name="quality">${[['economy','اقتصادی'],['standard','استاندارد'],['premium','ممتاز']].map(([v,l])=>`<option value="${v}" ${(p.quality||'standard')===v?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function projectForm(){return `${head('شروع یک داستان تازه','مشخصات پروژه‌ات را وارد کن؛ بیلتو همراه توست.')}<div class="grid-2"><section class="panel"><form id="project-form" novalidate><h2>چه چیزی می‌سازید؟</h2><div class="type-options">${[['residential','home'],['commercial','building'],['industrial','factory']].map(([v,i],n)=>`<label class="type-option"><input type="radio" name="type" value="${v}" ${n===0?'checked':''}>${icon(i)}${projectTypes[v]}</label>`).join('')}</div><div class="form-grid"><div class="form-field full"><label for="name">نام پروژه</label><input id="name" name="name" placeholder="مثلاً خانه ویلایی من" maxlength="80" required minlength="3"></div>${estimateFields()}</div><p class="form-error" id="form-error" role="alert"></p><div class="form-actions"><a href="#/projects" class="btn secondary">انصراف</a><button class="btn" type="submit">ایجاد پروژه ${icon('arrow',16)}</button></div></form></section><aside><div class="panel"><div class="dialog-art">${buildingArt()}</div><h2>یک خانه، هزار تصمیم.</h2><p class="muted small" style="margin-top:12px">مشخصات پروژه به شما کمک می‌کند برآورد اولیه داشته باشید و مسیر پیشرفت ساخت را مرحله‌به‌مرحله دنبال کنید.</p></div><div class="notice">${icon('shield',19)}<span>اطلاعات پروژه در همین مرورگر باقی می‌ماند. از تنظیمات می‌توانید خروجی اطلاعات بگیرید.</span></div></aside></div>`;}
function resultCard(result){return `<div class="estimate-result"><div class="eyebrow">هزینه تقریبی ساخت</div><div class="result-total">${money(result.total)}<small>تومان</small></div><div class="result-area">برای ${fa(result.totalArea)} مترمربع زیربنای کل · هر متر ${money(result.rate)} تومان</div><div class="stack-bar">${result.breakdown.map(b=>`<i style="width:${b.share*100}%"></i>`).join('')}</div><div class="result-breakdown">${result.breakdown.map(b=>`<div class="result-row"><span>${b.label}</span><b>${money(b.amount)}</b></div>`).join('')}</div></div>`;}
function estimatePage(){return `${head('برآورد هزینه ساخت','قبل از اولین قدم، تصویر روشن‌تری از هزینه‌ها داشته باش.')}<div class="grid-2"><section class="panel"><h2 style="margin-bottom:25px">مشخصات ساختمان</h2><form id="estimate-form" novalidate><div class="form-grid">${estimateFields()}</div><p id="form-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="submit">${icon('calculator',17)} محاسبه هزینه</button></div></form></section><aside class="estimate-aside"><div id="estimate-result">${resultCard(calculateEstimate({area:200,floors:2}))}</div><div class="notice">${icon('info',19)}<span>این برآورد با ضرایب نمونه محاسبه می‌شود و قیمت روز نیست. هزینه زمین و شرایط خاص پروژه در آن لحاظ نشده است. برای تصمیم نهایی، استعلام تخصصی بگیرید.</span></div></aside></div>`;}
function materialsPage(){let list=materials.filter(m=>(currentFilter==='همه'||m.category===currentFilter)&&`${m.name} ${m.brand}`.includes(searchTerm)&&(!savedOnly||state.favorites.includes(m.id)));return `${head('قیمت مصالح','انتخاب آگاهانه‌تر، ساخت‌وساز به‌صرفه‌تر.',`<button class="btn ${savedOnly?'':'secondary'}" data-action="saved-only">${icon('bookmark',16)} ذخیره‌شده‌ها (${fa(state.favorites.length)})</button>`)}<div class="saved-bar"><span>قیمت‌ها و تأمین‌کنندگان این نسخه نمایشی هستند.</span><a href="#/requests" class="text-btn">درخواست‌های من ${icon('arrow',14)}</a></div><div class="toolbar">${searchField('جست‌وجوی مصالح یا برند…')}</div><div style="margin-bottom:22px">${chips(['همه','آهن‌آلات','سیمان','آجر و بلوک','تأسیسات','شن و ماسه'])}</div><div class="material-grid">${list.length?list.map(m=>`<article class="material-card"><button class="bookmark ${state.favorites.includes(m.id)?'saved':''}" data-action="bookmark" data-id="${m.id}" aria-label="${state.favorites.includes(m.id)?'حذف از':'افزودن به'} ذخیره‌شده‌ها؛ ${m.name}" aria-pressed="${state.favorites.includes(m.id)}">${icon('bookmark',20)}</button><div class="material-art">${materialArt(m.visual)}</div><h3>${m.name}</h3><p>${m.brand} · ${m.unit}</p><div class="price-line"><strong>${money(m.price)} <small>تومان</small></strong>${changeLabel(m)}</div><a href="#/compare/${m.id}" class="btn soft">مقایسه تأمین‌کنندگان ${icon('arrow',14)}</a></article>`).join(''):empty()}</div>`;}
function comparePage(id){const m=materials.find(m=>m.id===id);if(!m)return notFound();const list=suppliers.map((s,i)=>({...s,price:Math.round(m.price*s.price/46500)}));const best=Math.min(...list.filter(s=>s.stock).map(s=>s.price));return `${head('مقایسه قیمت و موجودی',`${m.name} · قیمت هر ${m.unit} به تومان`,`<a href="#/materials" class="btn secondary">بازگشت ${icon('arrow',15)}</a>`)}<div class="panel"><div class="contractor-header" style="margin-bottom:25px"><div class="material-art">${materialArt(m.visual)}</div><div><h2>${m.name}</h2><p class="muted small">مشخصات و قیمت نمونه برای نمایش قابلیت مقایسه</p></div></div><div class="table-wrap"><table><thead><tr><th>تأمین‌کننده</th><th>قیمت (تومان)</th><th>موجودی</th><th>زمان ارسال</th><th>انتخاب</th></tr></thead><tbody>${list.map((s,i)=>`<tr><td><span class="supplier-name">${s.name}</span>${s.price===best?'<span class="best">کمترین قیمت</span>':''}<p class="muted small">${s.city}</p></td><td><b>${money(s.price)}</b></td><td><span class="stock ${s.stock?'':'off'}">${s.stock?'موجود':'ناموجود'}</span></td><td class="muted small">${s.delivery}</td><td><button class="btn small-btn ${s.stock?'':'secondary'}" ${s.stock?'':'disabled'} data-action="purchase" data-id="${m.id}" data-supplier="${i}">درخواست خرید</button></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('info',18)}این درخواست فقط در مرورگر ثبت می‌شود و هیچ خرید یا پرداختی انجام نمی‌دهد.</div></div>`;}
function contractorCard(c){return `<article class="contractor-card"><div class="contractor-header"><span class="company-logo ${c.color}">${c.initial}</span><div><h3>${c.name}<span class="verified">${icon('shield',14)}</span></h3><div class="rating">${icon('star',12)} ${fa(c.rating)} <span>· ${c.specialty}</span></div></div></div><div class="contractor-details"><span><b>${fa(c.projects)} پروژه</b>تکمیل‌شده</span><span><b>${fa(c.years)} سال</b>تجربه کاری</span><span><b>${c.city}</b>محل فعالیت</span></div><a href="#/contractor/${c.id}" class="btn soft">مشاهده پروفایل ${icon('arrow',15)}</a></article>`;}
function contractorsPage(){const list=contractors.filter(c=>(currentFilter==='همه'||c.specialty===currentFilter)&&`${c.name} ${c.city} ${c.specialty}`.includes(searchTerm));return `${head('همراهان ساخت شما','تیم مناسب را برای قدم بعدی پروژه پیدا کنید.')}<div class="saved-bar"><span>پروفایل‌ها و امتیازها برای نمایش برنامه نمونه‌سازی شده‌اند.</span></div><div class="toolbar">${searchField('جست‌وجوی پیمانکار یا شهر…')}</div><div style="margin-bottom:22px">${chips(['همه','ساخت‌وساز','بازسازی','سازه و تأسیسات'])}</div><div class="grid-3">${list.length?list.map(contractorCard).join(''):empty()}</div>`;}
function contractorPage(id){const c=contractors.find(c=>c.id===id);if(!c)return notFound();return `${head('پروفایل پیمانکار','یک همکاری خوب، با شناخت شروع می‌شود.',`<a href="#/contractors" class="btn secondary">همه پیمانکاران ${icon('arrow',15)}</a>`)}<div class="grid-2"><section class="panel"><div class="profile-hero"><span class="company-logo ${c.color}">${c.initial}</span><div><h2>${c.name} <span class="verified">${icon('shield',18)}</span></h2><p class="muted small" style="margin-top:7px">${c.specialty} · ${c.city}</p><div class="rating">${icon('star',14)} ${fa(c.rating)} <span>امتیاز نمایشی</span></div></div></div><div class="profile-stats"><div><strong>${fa(c.projects)}</strong><span>پروژه موفق</span></div><div><strong>${fa(c.years)}</strong><span>سال تجربه</span></div><div><strong>${fa(c.rating)}</strong><span>امتیاز کاربران</span></div></div><h3>درباره مجموعه</h3><p class="muted small" style="margin:12px 0 25px">${c.bio}</p><h3>نمایش نمونه پروژه‌ها</h3><div class="sample-projects">${[0,1,0].map(i=>`<div class="project-image">${buildingArt(i)}</div>`).join('')}</div></section><aside class="panel"><h2>قدم اول برای یک همکاری</h2><p class="muted small" style="margin:12px 0 22px">نیاز پروژه‌ات را بنویس و درخواست مشاوره را در فهرست خودت نگه دار.</p><button class="btn" style="width:100%" data-action="consult" data-id="${c.id}">${icon('people',17)} درخواست مشاوره</button><div class="notice">${icon('info',17)}اطلاعات پیمانکار نمونه است؛ درخواست به شخص یا شرکتی ارسال نمی‌شود.</div></aside></div>`;}
function guidePage(){const list=articles.filter(a=>(currentFilter==='همه'||a.category===currentFilter)&&`${a.title} ${a.desc}`.includes(searchTerm));return `${head('راهنمای ساخت‌وساز','از سؤال‌های کوچک تا تصمیم‌های بزرگ، کنار شما هستیم.')}<div class="toolbar">${searchField('جست‌وجوی آموزش…')}</div><div style="margin-bottom:22px">${chips(['همه','مراحل ساخت','مصالح و تجهیزات','نکات مهم'])}</div><div class="grid-3">${list.length?list.map(articleCard).join(''):empty()}</div><div class="tip-card" style="margin-top:25px">${icon('help',23)}<div><h3>هنوز سؤالی دارید؟</h3><p>پاسخ پرسش‌های رایج درباره بیلتو را اینجا پیدا کنید.</p><a class="text-btn" href="#/faq">سؤالات متداول ${icon('arrow',14)}</a></div></div>`;}
function articlePage(id){const a=articles.find(a=>a.id===id);if(!a)return notFound();return `<a class="text-btn" href="#/guide" style="margin-bottom:20px">${icon('arrow',15)} بازگشت به راهنما</a><article class="panel article-content"><div class="article-image">${art(a.visual)}</div><div class="eyebrow" style="margin-top:25px">${a.category} · ${fa(a.time)} دقیقه مطالعه</div><h1>${a.title}</h1><p>${a.desc}</p>${a.body.map(p=>`<p>${p}</p>`).join('')}<div class="notice">${icon('book',19)}این مطالب راهنمای عمومی هستند؛ اجرای پروژه باید مطابق ضوابط محل و نظر متخصصان دارای صلاحیت انجام شود.</div></article>`;}
function faqPage(){const list=faqs.filter(([q,a])=>`${q} ${a}`.includes(searchTerm));return `<div class="faq-hero"><span class="stat-icon">${icon('help',27)}</span><h1>چطور می‌توانیم کمکتان کنیم؟</h1><p>پاسخ سؤالات پرتکرار، یک قدم نزدیک‌تر.</p>${searchField('جست‌وجوی سؤال…')}</div><div class="faq-list">${list.length?list.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join(''):empty()}</div>`;}
function projectDetail(id){const p=state.projects.find(p=>p.id===id);if(!p)return notFound();const tabs=[['overview','خلاصه پروژه'],['stages','مراحل ساخت'],['costs','هزینه‌ها'],['team','پیمانکاران']];return `${head(esc(p.name),`${esc(p.city)} · ${projectTypes[p.type]} · ${fa(p.area*p.floors)} مترمربع زیربنا`,`<a href="#/projects" class="btn secondary">همه پروژه‌ها ${icon('arrow',15)}</a>`)}<div class="tab-bar" role="tablist">${tabs.map(([id,l])=>`<button role="tab" aria-selected="${detailTab===id}" class="tab ${detailTab===id?'active':''}" data-action="detail-tab" data-id="${id}">${l}</button>`).join('')}</div>${detailTab==='overview'?`<div class="grid-2"><section class="panel"><h2>هر قدم، نزدیک‌تر به خانه</h2><div class="project-overview"><div class="progress-ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="51" fill="none" stroke="#edf3fa" stroke-width="8"/><circle cx="60" cy="60" r="51" fill="none" stroke="#0867ef" stroke-width="8" stroke-linecap="round" stroke-dasharray="${p.progress/100*320.44} 320.44"/></svg><div class="ring-label">${fa(p.progress)}٪<small>پیشرفت پروژه</small></div></div><div><p class="eyebrow">مرحله فعلی پروژه</p><h2 style="margin-top:9px">${stages[p.stage]}</h2><div style="margin-top:16px"><button class="text-btn" data-action="detail-tab" data-id="stages">مدیریت مراحل ${icon('arrow',14)}</button></div></div></div><div class="info-grid">${[['نوع سازه',p.structure==='steel'?'اسکلت فلزی':'اسکلت بتنی'],['تعداد طبقات',fa(p.floors)+' طبقه'],['مساحت هر طبقه',fa(p.area)+' مترمربع'],['شهر پروژه',esc(p.city)]].map(([k,v])=>`<div class="info-item">${k}<strong>${v}</strong></div>`).join('')}</div></section><aside>${resultCard(calculateEstimate(p))}<a class="btn secondary" style="width:100%;margin-top:17px" href="#/estimate">${icon('calculator',17)} برآورد یک سناریوی دیگر</a></aside></div>`:detailTab==='stages'?`<section class="panel" style="max-width:820px"><h2>مسیر پروژه شما</h2><p class="muted small" style="margin-top:8px">مرحله‌ای را که در آن هستید انتخاب کنید تا پیشرفت پروژه به‌روز شود.</p><ol class="timeline">${stages.map((s,i)=>`<li class="${i<p.stage?'done':i===p.stage?'current':''}"><span class="step-number">${i<p.stage?icon('check',15):fa(i+1)}</span><div><h3>${s}</h3><p>${i<p.stage?'انجام‌شده':i===p.stage?'مرحله فعلی':'در پیش رو'}</p>${i!==p.stage?`<button class="text-btn" data-action="set-stage" data-id="${p.id}" data-stage="${i}">انتخاب این مرحله</button>`:''}</div></li>`).join('')}</ol></section>`:detailTab==='costs'?`<div class="grid-2"><section>${resultCard(calculateEstimate(p))}</section><aside class="notice no-margin">${icon('info',20)}این ارقام برآورد اولیه با نرخ‌های نمونه هستند. هزینه واقعی پرداخت‌شده در این نسخه ثبت نمی‌شود.</aside></div>`:`<div class="grid-3">${contractors.slice(0,3).map(contractorCard).join('')}</div>`}`;}
function requestsPage(){return `${head('درخواست‌های من','یادداشت درخواست‌های خرید و مشاوره؛ ذخیره‌شده در این مرورگر.')}<div class="notice" style="margin:0 0 23px">${icon('info',18)}درخواست‌ها برای تأمین‌کننده یا پیمانکار ارسال نشده‌اند و تعهد خرید ایجاد نمی‌کنند.</div>${state.requests.length?state.requests.slice().reverse().map(r=>`<article class="request-card"><div><h3>${esc(r.title)}</h3><p>${esc(r.detail)}</p><p>${new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium'}).format(new Date(r.createdAt))}</p></div><span class="request-status">ثبت محلی</span></article>`).join(''):empty('هنوز درخواستی ندارید','از مقایسه مصالح یا پروفایل پیمانکار یک درخواست ثبت کنید.',`<a class="btn" href="#/materials">مشاهده مصالح</a>`)}`;}
function settingsPage(){const p=state.profile;return `${head('حساب کاربری و تنظیمات','بیلتو را برای خودتان شخصی کنید.')}<div class="settings-layout"><nav class="settings-nav" aria-label="تنظیمات"><a href="#/landing" class="btn secondary">معرفی بیلتو</a>${[['profile','user','اطلاعات حساب'],['preferences','bell','ترجیحات نمایش'],['data','download','اطلاعات من']].map(([id,i,l])=>`<button class="${settingTab===id?'active':''}" data-action="setting-tab" data-id="${id}">${icon(i,17)}${l}</button>`).join('')}<a class="btn secondary" href="#/requests">${icon('project',16)}درخواست‌های من</a></nav><section class="panel">${settingTab==='profile'?`<div class="settings-profile"><span class="avatar">${esc(p.name.slice(0,1))}</span><div><h2>${esc(p.name)}</h2><p class="muted small">حساب محلی بیلتو</p></div></div><form id="profile-form"><div class="form-grid"><div class="form-field"><label for="profile-name">نام نمایشی</label><input id="profile-name" name="name" value="${esc(p.name)}" required maxlength="50"></div><div class="form-field"><label for="profile-phone">شماره موبایل (اختیاری)</label><input id="profile-phone" name="phone" value="${esc(p.phone)}" inputmode="tel" dir="ltr" maxlength="11"></div><div class="form-field"><label for="profile-email">ایمیل (اختیاری)</label><input id="profile-email" name="email" value="${esc(p.email)}" type="email" dir="ltr"></div><div class="form-field"><label for="city">شهر</label><select id="city" name="city">${cityOptions(p.city)}</select></div></div><p class="form-error" id="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="submit">ذخیره تغییرات</button></div></form>`:settingTab==='preferences'?`<h2>ترجیحات شما</h2><div class="settings-row"><div><h3>پیشنهادهای آموزشی</h3><p>نمایش نکته و راهنمای ساخت در داشبورد</p></div><label class="toggle"><input type="checkbox" id="tips-toggle" ${state.settings.tips?'checked':''} aria-label="نمایش پیشنهادهای آموزشی"><span></span></label></div><div class="settings-row"><div><h3>راهنمای شروع</h3><p>یک بار دیگر با امکانات بیلتو آشنا شوید.</p></div><button class="btn secondary" data-action="onboard">مشاهده راهنما</button></div>`:`<h2>اطلاعات شما، در اختیار شما</h2><div class="settings-row"><div><h3>دریافت خروجی اطلاعات</h3><p>پروژه‌ها، پروفایل و درخواست‌ها را در قالب JSON دانلود کنید.</p></div><button class="btn secondary" data-action="export">${icon('download',17)} دریافت فایل</button></div><div class="settings-row"><div><h3>پروژه‌های ذخیره‌شده</h3><p>${fa(state.projects.length)} پروژه و ${fa(state.requests.length)} درخواست در این مرورگر</p></div><a class="text-btn" href="#/projects">مشاهده ${icon('arrow',14)}</a></div><div class="notice">${icon('shield',18)}حذف داده‌های سایت از مرورگر باعث پاک شدن این اطلاعات می‌شود. این نسخه به سرور و حساب کاربری آنلاین متصل نیست.</div>`}</section></div>`;}
function notFound(){return `${head('صفحه پیدا نشد')} ${empty('این صفحه در دسترس نیست','از منوی اصلی بخش مورد نظر را انتخاب کنید.',`<a class="btn" href="#/dashboard">بازگشت به خانه</a>`)}`;}

function authPage(mode){return `<div class="auth-layout"><div class="auth-visual">${brand()}<h1>از زمین تا خانه،<br>با خیال راحت بساز!</h1><p>همه چیز برای ساختن فردایی بهتر؛ از اولین ایده تا آخرین آجر.</p>${buildingArt(0,true)}</div><div class="auth-form-wrap"><section class="auth-form">${brand()}<h2>${mode==='verify'?'کد تأیید نمایشی':mode==='register'?'به بیلتو خوش آمدید':'ورود به حساب کاربری'}</h2><p class="muted">${mode==='verify'?'برای تجربه مسیر ورود، کد ۱۲۳۴۵ را وارد کنید.':'این فرم فقط مسیر نمایشی ورود را اجرا می‌کند.'}</p><form id="auth-form" data-mode="${mode}"><div class="form-field"><label for="auth-value">${mode==='verify'?'کد تأیید':'شماره موبایل'}</label><input id="auth-value" name="value" class="${mode==='verify'?'otp-input':''}" inputmode="numeric" dir="ltr" maxlength="${mode==='verify'?5:11}" placeholder="${mode==='verify'?'•••••':'09xxxxxxxxx'}" autocomplete="off" required></div><p class="form-error" id="form-error" role="alert"></p><button class="btn" type="submit">${mode==='verify'?'تأیید و ورود':'ادامه نمایشی'} ${icon('arrow',15)}</button></form><p class="auth-back">${mode==='register'?'حساب دارید؟ <a href="#/login">ورود</a>':'اولین بار است؟ <a href="#/register">ثبت‌نام نمایشی</a>'}</p><p class="auth-back"><a href="#/dashboard">ورود مستقیم به نسخه نمایشی</a></p><div class="notice">${icon('info',17)}پیامکی ارسال نمی‌شود. احراز هویت واقعی به سرویس پیامک و سرور نیاز دارد.</div></section></div></div>`;}
function landingPage(){return `<main class="landing"><header>${brand()}<a class="btn secondary" href="#/login">ورود به حساب ${icon('arrow',16)}</a></header><section class="landing-content"><div class="hero-tag"><i></i> همراه شما در تمام مسیر ساخت</div><h1>از زمین تا خانه،<br><span>با خیال راحت بساز!</span></h1><p>همه چیز برای ساختن خانه‌ای که در ذهن دارید.<br>پروژه‌ها، برآورد هزینه، مصالح و همراهان ساخت؛ در یک جا.</p><div class="landing-actions"><a class="btn" href="#/dashboard">شروع کنید ${icon('arrow',17)}</a><a class="text-btn" href="#/register">ثبت‌نام نمایشی</a></div><div class="landing-benefits"><span>${icon('shield',17)}مسیر شفاف ساخت</span><span>${icon('calculator',17)}تصویر روشن هزینه‌ها</span><span>${icon('people',17)}همراهان ساخت</span></div></section><div class="landing-building">${buildingArt(0,true)}</div><footer>بیلتو؛ برای ساختن فردایی بهتر <a href="#/faq">سؤالات متداول</a></footer></main>`;}
function render({keepScroll=false}={}){
 const oldY=scrollY;
 const r=route(); let page;
 if(r==='/landing'){document.title='از زمین تا خانه | بیلتو';$('#app').innerHTML=landingPage();return;}
 if(['/login','/register','/verify'].includes(r)){document.title='ورود | بیلتو';$('#app').innerHTML=authPage(r.slice(1));return;}
 if(r==='/dashboard')page=dashboard();else if(r==='/projects')page=projectsPage();else if(r==='/new-project')page=projectForm();else if(r==='/estimate')page=estimatePage();else if(r==='/materials')page=materialsPage();else if(r.startsWith('/compare/'))page=comparePage(r.split('/')[2]);else if(r==='/contractors')page=contractorsPage();else if(r.startsWith('/contractor/'))page=contractorPage(r.split('/')[2]);else if(r==='/guide')page=guidePage();else if(r.startsWith('/article/'))page=articlePage(r.split('/')[2]);else if(r==='/faq')page=faqPage();else if(r==='/settings')page=settingsPage();else if(r==='/requests')page=requestsPage();else if(r.startsWith('/project/'))page=projectDetail(decodeURIComponent(r.split('/')[2]));else page=notFound();
 $('#app').innerHTML=shell(page);$('#sidebar').inert=matchMedia('(max-width:720px)').matches;document.title=($('h1')?.textContent||'از زمین تا خانه')+' | بیلتو';if(keepScroll)window.scrollTo(0,oldY);
}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function openModal(title,subtitle,body){lastFocus=document.activeElement;activeDialog='generic';$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-action="close-modal" aria-label="بستن">${icon('close',18)}</button></div>${subtitle?`<p>${subtitle}</p>`:''}${body}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input, .modal button')?.focus(),30);}
function closeModal(){const wasOnboard=activeDialog==='onboard';$('#modal-root').innerHTML='';document.body.style.overflow='';activeDialog=null;if(wasOnboard){state.onboarded=true;save();}if(lastFocus?.isConnected)lastFocus.focus();}
function onboarding(step=0){const slides=[['راهنمای قدم‌به‌قدم ساخت','با یک مسیر روشن، از طراحی تا تحویل خانه پیش بروید.'],['هزینه‌ها را روشن‌تر ببینید','مشخصات ساختمان را وارد کنید و سناریوهای هزینه را مقایسه کنید.'],['همه پروژه‌ها، یک جا','پیشرفت پروژه و مصالح مورد علاقه‌تان همیشه در دسترس شماست.']];openModal('','',`<div class="onboarding"><div class="dialog-art">${buildingArt(step%2)}</div><h2 id="onboard-title">${slides[step][0]}</h2><p>${slides[step][1]}</p><div class="onboard-dots">${slides.map((_,i)=>`<i class="${i===step?'active':''}"></i>`).join('')}</div><button class="btn" data-action="onboard-next" data-step="${step}">${step===2?'شروع می‌کنیم':'بعدی'} ${icon('arrow',16)}</button><button class="text-btn" data-action="close-modal">رد کردن آموزش</button></div>`);$('.modal').setAttribute('aria-labelledby','onboard-title');activeDialog='onboard';}

document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='menu-open'){$('#sidebar').inert=false;$('#sidebar').classList.add('open');document.body.style.overflow='hidden';return;}
 if(action==='menu-close'){$('#sidebar').classList.remove('open');$('#sidebar').inert=matchMedia('(max-width:720px)').matches;document.body.style.overflow='';return;}
 if(action==='close-modal'){closeModal();return;}
 if(action==='filter'){currentFilter=b.dataset.value;render({keepScroll:true});return;}
 if(action==='saved-only'){savedOnly=!savedOnly;render({keepScroll:true});return;}
 if(action==='bookmark'){const id=b.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(v=>v!==id):[...state.favorites,id];save();render({keepScroll:true});return;}
 if(action==='detail-tab'){detailTab=b.dataset.id;render({keepScroll:true});return;}
 if(action==='setting-tab'){settingTab=b.dataset.id;render({keepScroll:true});return;}
 if(action==='set-stage'){const p=state.projects.find(p=>p.id===b.dataset.id);if(p){p.stage=Number(b.dataset.stage);p.progress=Math.round(p.stage/(stages.length-1)*100);save();render({keepScroll:true});toast('مرحله و پیشرفت پروژه به‌روز شد.');}return;}
 if(action==='notifications'){openModal('اعلان‌ها','به میز کار بیلتو خوش آمدید.',`<div class="modal-list">${icon('home',22)}<div><h3>همراه مسیر ساخت شما هستیم</h3><p>از پروژه جدید شروع کنید یا پروژه‌های نمونه را ببینید.</p></div></div><div class="modal-list">${icon('info',22)}<div><h3>نسخه نمایشی فعال است</h3><p>قیمت‌ها و پیمانکاران نمونه هستند. اطلاعات شما در مرورگر ذخیره می‌شود.</p></div></div><div class="form-actions"><button class="btn" data-action="close-modal">متوجه شدم</button></div>`);return;}
 if(action==='purchase'){const m=materials.find(m=>m.id===b.dataset.id);const s=suppliers[Number(b.dataset.supplier)];openModal('ثبت درخواست خرید',`${m.name} · ${s.name}`,`<form id="purchase-form" data-material="${m.id}" data-supplier="${b.dataset.supplier}"><div class="form-grid"><div class="form-field"><label for="quantity">مقدار مورد نیاز (${m.unit})</label><input name="quantity" id="quantity" inputmode="decimal" value="1" required></div><div class="form-field"><label for="request-note">توضیحات (اختیاری)</label><textarea name="note" id="request-note" maxlength="500" placeholder="مثلاً زمان مورد نیاز برای تحویل"></textarea></div></div><p class="form-error" id="modal-error" role="alert"></p><div class="notice">${icon('info',17)}این درخواست فقط در مرورگر شما ذخیره می‌شود و به فروشنده ارسال نمی‌شود.</div><div class="form-actions"><button class="btn" type="submit">ذخیره درخواست</button></div></form>`);return;}
 if(action==='consult'){const c=contractors.find(c=>c.id===b.dataset.id);openModal('درخواست مشاوره',c.name,`<form id="consult-form" data-contractor="${c.id}"><div class="form-grid"><div class="form-field"><label for="consult-project">پروژه مرتبط</label><select id="consult-project" name="project"><option value="">هنوز پروژه‌ای ندارم</option>${state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div><div class="form-field"><label for="consult-note">نیاز پروژه شما</label><textarea id="consult-note" name="note" placeholder="درباره پروژه و نوع همکاری بنویسید…" required minlength="5" maxlength="500"></textarea></div></div><p class="form-error" id="modal-error" role="alert"></p><div class="notice">${icon('info',17)}درخواست محلی است و به پیمانکار ارسال نمی‌شود.</div><div class="form-actions"><button class="btn" type="submit">ذخیره درخواست</button></div></form>`);return;}
 if(action==='export'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='bilto-data-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('فایل اطلاعات آماده دریافت شد.');return;}
 if(action==='onboard'){onboarding();return;}
 if(action==='onboard-next'){const step=Number(b.dataset.step);if(step<2)onboarding(step+1);else{closeModal();toast('به بیلتو خوش آمدید!');}return;}
});
document.addEventListener('input',e=>{
 if(e.target.id==='page-search'){const input=e.target;const cursor=input.selectionStart;searchTerm=input.value;render({keepScroll:true});const next=$('#page-search');next.focus();next.setSelectionRange(cursor,cursor);}
});
document.addEventListener('change',e=>{if(e.target.id==='tips-toggle'){state.settings.tips=e.target.checked;save();toast('ترجیحات ذخیره شد.');}});
document.addEventListener('submit',e=>{
 const form=e.target;if(!['project-form','estimate-form','profile-form','purchase-form','consult-form','auth-form','global-search'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));
 try{
  if(form.id==='global-search'){searchTerm=String(data.q).trim();currentFilter='همه';if(route()!=='/guide')location.hash='/guide';else render();return;}
  if(form.id==='project-form'){const p=createProject(data);state.projects.push(p);save();detailTab='overview';location.hash='/project/'+p.id;toast('پروژه جدید ایجاد شد.');}
  if(form.id==='estimate-form'){const r=calculateEstimate(data);$('#estimate-result').innerHTML=resultCard(r);$('#form-error').textContent='';toast('برآورد هزینه به‌روز شد.');}
  if(form.id==='profile-form'){if(!data.name.trim())throw new Error('نام نمایشی را وارد کنید.');const phone=normalizeDigits(data.phone).trim();if(phone&&!/^09\d{9}$/.test(phone))throw new Error('شماره موبایل باید ۱۱ رقم و با ۰۹ شروع شود.');state.profile={name:data.name.trim(),phone,email:data.email.trim(),city:data.city};save();render({keepScroll:true});toast('اطلاعات حساب ذخیره شد.');}
  if(form.id==='purchase-form'){const qty=Number(normalizeDigits(data.quantity));if(!Number.isFinite(qty)||qty<=0||qty>10000000)throw new Error('مقدار باید بیشتر از صفر و کمتر از ۱۰ میلیون باشد.');const m=materials.find(m=>m.id===form.dataset.material);const s=suppliers[Number(form.dataset.supplier)];state.requests.push({id:crypto.randomUUID(),type:'purchase',title:`خرید ${m.name} از ${s.name}`,detail:`${fa(qty)} ${m.unit}${data.note?' · '+data.note:''}`,createdAt:new Date().toISOString()});save();closeModal();location.hash='/requests';toast('درخواست در مرورگر ذخیره شد.');}
  if(form.id==='consult-form'){if(data.note.trim().length<5)throw new Error('لطفاً نیاز پروژه را در حداقل ۵ کاراکتر بنویسید.');const c=contractors.find(c=>c.id===form.dataset.contractor);const p=state.projects.find(p=>p.id===data.project);state.requests.push({id:crypto.randomUUID(),type:'consult',title:`مشاوره با ${c.name}`,detail:`${p?p.name+' · ':''}${data.note.trim()}`,createdAt:new Date().toISOString()});save();closeModal();location.hash='/requests';toast('درخواست مشاوره ذخیره شد.');}
  if(form.id==='auth-form'){const value=normalizeDigits(data.value);if(form.dataset.mode==='verify'){if(value!=='12345')throw new Error('کد نمایشی ۱۲۳۴۵ است.');pendingOnboarding=true;location.hash='/dashboard';}else{if(!/^09\d{9}$/.test(value))throw new Error('شماره موبایل را به صورت ۱۱ رقم با شروع ۰۹ وارد کنید.');state.profile.phone=value;save();location.hash='/verify';}}
 }catch(err){const el=form.querySelector('[role="alert"]');if(el)el.textContent=err.message;else toast(err.message);}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){if($('.modal'))closeModal();if($('#sidebar')){$('#sidebar').classList.remove('open');$('#sidebar').inert=matchMedia('(max-width:720px)').matches;}document.body.style.overflow='';}
 if(e.key==='Tab'&&$('.modal')){const focusable=[...$('.modal').querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
window.addEventListener('hashchange',()=>{const preserveSearch=route()==='/guide'&&document.activeElement?.closest('#global-search');if(!preserveSearch)searchTerm='';currentFilter='همه';detailTab='overview';closeModal();render();window.scrollTo(0,0);if(pendingOnboarding){pendingOnboarding=false;onboarding();}});
matchMedia('(max-width:720px)').addEventListener('change',e=>{if($('#sidebar')){$('#sidebar').inert=e.matches&&!$('#sidebar').classList.contains('open');}});
render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
